css:
.pm-bias-scope {
  --ink: #1a1a1a;
  --muted: #666;
  --accent: #003366;
  --warm: #b30059;
  --line: #ddd;
  --paper: #f9f9f9;

  font-family: 'Georgia', 'Times New Roman', serif;
  background-color: var(--paper);
  color: var(--ink);
  padding: 2rem 1rem;
  line-height: 1.6;
  box-sizing: border-box;
}

.pm-bias-scope * {
  box-sizing: border-box;
}

.pm-header {
  margin-bottom: 2rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 1rem;
}

.pm-title {
  font-size: 24px;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
}

.pm-lead {
  font-size: 15px;
  color: var(--muted);
  margin: 0 0 1rem 0;
}

.pm-sources {
  display: flex;
  gap: 0.5rem;
}

.pm-btn-source {
  background: transparent;
  border: 1px solid var(--accent);
  color: var(--accent);
  padding: 4px 8px;
  font-size: 13px;
  cursor: pointer;
  font-family: monospace;
}

.pm-btn-source:hover {
  background: var(--accent);
  color: #fff;
}

.pm-content-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media (min-width: 768px) {
  .pm-content-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.pm-text-col {
  font-size: 15px;
}

.pm-subtitle {
  font-size: 18px;
  color: var(--ink);
  margin-top: 0;
}

.pm-paragraph {
  margin-bottom: 1rem;
  text-align: justify;
}

.pm-assumptions-box {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1rem;
  margin-top: 1.5rem;
  font-size: 14px;
}

.pm-box-title {
  font-size: 14px;
  margin: 0 0 0.5rem 0;
  color: var(--warm);
  font-family: monospace;
}

.pm-list {
  margin: 0;
  padding-left: 1.2rem;
}

.pm-list li {
  margin-bottom: 0.5rem;
  color: var(--muted);
}

.pm-stepper-container {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  border-radius: 4px;
}

.pm-step-indicator {
  display: flex;
  align-items: center;
  margin-bottom: 1.5rem;
}

.pm-step-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--line);
  color: var(--muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-family: monospace;
  z-index: 1;
}

.pm-step-dot.active {
  background: var(--accent);
  color: #fff;
}

.pm-step-line {
  flex: 1;
  height: 2px;
  background: var(--line);
  margin: 0 8px;
}

.pm-step-content {
  animation: pmFadeIn 0.3s ease;
}

@keyframes pmFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.pm-step-title {
  font-size: 16px;
  margin: 0 0 0.5rem 0;
  color: var(--accent);
  font-family: monospace;
}

.pm-step-desc {
  font-size: 14px;
  color: var(--muted);
  margin: 0 0 1rem 0;
}

.pm-label {
  display: block;
  font-size: 13px;
  margin-bottom: 0.5rem;
  font-family: monospace;
}

.pm-select {
  width: 100%;
  padding: 8px;
  font-size: 14px;
  border: 1px solid var(--line);
  background: #fff;
  margin-bottom: 1rem;
}

.pm-word-sets-display {
  background: #f4f4f4;
  padding: 1rem;
  margin-bottom: 1rem;
  font-size: 14px;
}

.pm-word-set {
  margin-bottom: 0.5rem;
}

.pm-label-small {
  font-family: monospace;
  color: var(--muted);
  font-size: 12px;
  display: block;
}

.pm-data-value {
  font-weight: bold;
  color: var(--ink);
}

.pm-btn-next, .pm-btn-prev, .pm-btn-reset {
  padding: 8px 16px;
  font-size: 13px;
  cursor: pointer;
  border: none;
  margin-right: 0.5rem;
}

.pm-btn-next {
  background: var(--accent);
  color: #fff;
}

.pm-btn-prev, .pm-btn-reset {
  background: #eee;
  color: var(--ink);
}

.pm-vector-viz {
  background: #fff;
  border: 1px solid var(--line);
  margin: 1rem 0;
  text-align: center;
}

.pm-svg-viz {
  width: 100%;
  height: auto;
  max-width: 200px;
}

.pm-caption {
  font-size: 12px;
  color: var(--muted);
  margin: 0.5rem 0 0 0;
  font-style: italic;
}

.pm-formula-box {
  background: #f4f4f4;
  padding: 0.5rem;
  text-align: center;
  margin: 1rem 0;
  font-family: monospace;
  font-size: 13px;
  color: var(--accent);
}

.pm-result-card {
  border: 1px solid var(--warm);
  padding: 1rem;
  margin: 1rem 0;
  background: #fff;
}

.pm-result-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: 14px;
}

.pm-interpretation {
  font-size: 13px;
  color: var(--muted);
  margin-top: 1rem;
  border-top: 1px solid var(--line);
  padding-top: 0.5rem;
}

javascript:
(function() {
  const scope = document.querySelector('.pm-bias-scope');
  if (!scope) return;

  // Safe data access
  const tables = window.paperMindData?.tables || [];
  const sources = window.paperMindData?.sources || {};

  // Find Table 1
  const table1 = tables.find(t => t.id === 'p4-table-1');
  const rows = table1?.rows || [];

  // Elements
  const testSelect = scope.querySelector('#pm-test-select');
  const targetWordsEl = scope.querySelector('#pm-target-words');
  const attributeWordsEl = scope.querySelector('#pm-attribute-words');
  const resultFtEl = scope.querySelector('#pm-result-ft');
  const resultW2vEl = scope.querySelector('#pm-result-w2v');
  const resultIatEl = scope.querySelector('#pm-result-iat');
  const interpretationEl = scope.querySelector('#pm-interpretation-text');

  const stepContents = scope.querySelectorAll('.pm-step-content');
  const stepDots = scope.querySelectorAll('.pm-step-dot');

  const btnStep1Next = scope.querySelector('#pm-btn-step1-next');
  const btnStep2Next = scope.querySelector('#pm-btn-step2-next');
  const btnStep2Prev = scope.querySelector('#pm-btn-step2-prev');
  const btnStep3Prev = scope.querySelector('#pm-btn-step3-prev');
  const btnReset = scope.querySelector('#pm-btn-reset');

  // State
  let currentStep = 1;
  let selectedRow = null;

  // Initialize Select
  function initSelect() {
    if (!testSelect || rows.length === 0) {
      if (testSelect) testSelect.innerHTML = '<option value="" disabled>数据不可用</option>';
      return;
    }
    testSelect.innerHTML = '<option value="" disabled selected>选择测试用例...</option>';
    rows.forEach(row => {
      const opt = document.createElement('option');
      opt.value = row.id;
      const testNo = row.values['Test no.'] || 'Unknown';
      const target = row.values['Target Words'] || 'Unknown';
      opt.textContent = `Test ${testNo}: ${target}`;
      testSelect.appendChild(opt);
    });
  }

  // Update Step UI
  function updateStep(step) {
    currentStep = step;
    stepContents.forEach((el, idx) => {
      if (idx + 1 === step) {
        el.hidden = false;
      } else {
        el.hidden = true;
      }
    });
    stepDots.forEach((el, idx) => {
      if (idx + 1 === step) {
        el.classList.add('active');
      } else {
        el.classList.remove('active');
      }
    });
  }

  // Handle Selection
  function handleSelectChange() {
    const rowId = testSelect.value;
    const row = rows.find(r => r.id === rowId);
    if (!row) return;
    selectedRow = row;

    targetWordsEl.textContent = row.values['Target Words'] || '-';
    attributeWordsEl.textContent = row.values['Attribute Words'] || '-';
  }

  // Handle Results
  function showResults() {
    if (!selectedRow) return;
    const v = selectedRow.values;

    // Parse numbers safely
    const ft = v['FT'] !== null ? Number(v['FT']) : null;
    const w2v = v['w2v'] !== null ? Number(v['w2v']) : null;
    const iat = v['IAT'] !== null ? Number(v['IAT']) : null;

    resultFtEl.textContent = ft !== null ? ft.toFixed(2) : 'null';
    resultW2vEl.textContent = w2v !== null ? w2v.toFixed(2) : 'null';
    resultIatEl.textContent = iat !== null ? iat.toFixed(2) : 'null';

    // Interpretation logic based on paper text
    let msg = '效应量正值表示存在预期方向的偏见（如目标词 1 更关联属性词 1）。';
    if (ft !== null && iat !== null) {
      if (ft > 0 && iat > 0) {
        msg += ' fastText 结果与人类 IAT 方向一致。';
      }
      if (Math.abs(ft - iat) < Math.abs(w2v - iat)) {
        msg += ' 在此测试中，fastText 比 word2vec 更接近人类结果。';
      }
    }
    // Specific limitation note for certain tests based on paper text (Test 3, 6, 8)
    const testNo = v['Test no.'];
    if (['3', '6', '8'].includes(testNo)) {
      msg += ' 注：论文指出此类测试因歌词数据集中相关词实例少，向量可能不准确。';
    }
    interpretationEl.textContent = msg;
  }

  // Event Listeners
  if (testSelect) {
    testSelect.addEventListener('change', handleSelectChange);
  }

  if (btnStep1Next) {
    btnStep1Next.addEventListener('click', () => {
      if (!selectedRow) {
        alert('请先选择一个测试用例');
        return;
      }
      updateStep(2);
    });
  }

  if (btnStep2Next) {
    btnStep2Next.addEventListener('click', () => {
      showResults();
      updateStep(3);
    });
  }

  if (btnStep2Prev) {
    btnStep2Prev.addEventListener('click', () => updateStep(1));
  }

  if (btnStep3Prev) {
    btnStep3Prev.addEventListener('click', () => updateStep(2));
  }

  if (btnReset) {
    btnReset.addEventListener('click', () => {
      if (testSelect) testSelect.value = '';
      selectedRow = null;
      targetWordsEl.textContent = '-';
      attributeWordsEl.textContent = '-';
      resultFtEl.textContent = '-';
      resultW2vEl.textContent = '-';
      resultIatEl.textContent = '-';
      interpretationEl.textContent = '-';
      updateStep(1);
    });
  }

  // Source Buttons
  const sourceBtns = scope.querySelectorAll('.pm-btn-source');
  sourceBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Host kernel handles data-source attribute
      // No action needed here per spec
    });
  });

  // Init
  initSelect();
  updateStep(1);

})();
